export function publicUser(row: {
  user_id: string;
  email: string;
  name: string;
  lang: string;
  person_id: string | null;
}): PublicUser {
  return {
    user_id: row.user_id,
    email: row.email,
    name: row.name,
    lang: row.lang,
    person_id: row.person_id,
  };
}

